//! Native DOM position masks over real inert, Attr and child identities.
use super::*;
fn fixture()->(Document,Forms,Page){let mut doc=crate::html::parse("<!doctype html><html><body></body></html>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();page.set_location(&crate::navigation::address("https://inert-position.test/",&crate::navigation::Location::home()).unwrap());assert_eq!(page.start(&mut doc,&mut forms,&[]).errors,0);(doc,forms,page)}
fn run(doc:&mut Document,forms:&mut Forms,page:&mut Page,source:&str){assert_eq!(page.console_eval(doc,forms,source).errors,0,"{source}\n{}",page.report());}
#[test]
fn inert_position_canonical_descriptor_nonnullable_brands_and_no_coercion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var method=Node.prototype.compareDocumentPosition,descriptor=Object.getOwnPropertyDescriptor(Node.prototype,'compareDocumentPosition'),node=new Document(),touched=0;if(method.name!=='compareDocumentPosition'||method.length!==1||!descriptor.writable||!descriptor.enumerable||!descriptor.configurable||node.compareDocumentPosition!==method||method.call(node,node)!==0)throw 'canonical Node operation';for(var bad of [{},null,Node.prototype,window]){var caught=false;try{method.call(bad,node);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'receiver brand';}for(var bad of [null,undefined,1,Symbol(),{toString:function(){touched++;return node;}}]){var caught=false;try{method.call(node,bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'nonnullable Node brand';}var caught=false;try{method.call(node);}catch(e){caught=e instanceof TypeError;}if(!caught||touched)throw 'required noncoercing argument';try{new method(node);throw 'constructible';}catch(e){if(!(e instanceof TypeError))throw e;}
"#);}
#[test]
fn inert_position_current_document_ancestry_siblings_attrs_and_adoption(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var impl=document.implementation,dt=impl.createDocumentType('Root','',''),owner=impl.createDocument(null,'Root',dt),root=owner.documentElement,a=owner.createElement('A'),b=owner.createElement('B'),text=owner.createTextNode('native');root.appendChild(a);root.appendChild(b);a.appendChild(text);if(owner.compareDocumentPosition(root)!==20||root.compareDocumentPosition(owner)!==10||dt.compareDocumentPosition(root)!==4||root.compareDocumentPosition(dt)!==2||a.compareDocumentPosition(text)!==20||text.compareDocumentPosition(a)!==10||a.compareDocumentPosition(b)!==4||b.compareDocumentPosition(a)!==2)throw 'actual document and sibling order';a.setAttribute('first','1');a.setAttributeNS('urn:attr','p:second','2');var first=a.getAttributeNode('first'),second=a.getAttributeNodeNS('urn:attr','second');if(first.compareDocumentPosition(second)!==36||second.compareDocumentPosition(first)!==34||a.compareDocumentPosition(first)!==20||first.compareDocumentPosition(a)!==10||root.compareDocumentPosition(first)!==20||first.compareDocumentPosition(text)!==4||text.compareDocumentPosition(first)!==2||a.contains(first))throw 'Attr owner ordering differs from containment';a.removeAttributeNode(first);var order=first.compareDocumentPosition(a);if((order!==35&&order!==37)||(order^a.compareDocumentPosition(first))!==6||first.compareDocumentPosition(a)!==order)throw 'detached Attr order';root.insertBefore(b,a);if(a.compareDocumentPosition(b)!==2||b.compareDocumentPosition(a)!==4)throw 'live sibling move';var target=new Document();target.adoptNode(a);var order=target.compareDocumentPosition(a);if((order&33)!==33||(order^a.compareDocumentPosition(target))!==6||a.compareDocumentPosition(text)!==20||a.ownerDocument!==target)throw 'owner document is not parent';target.appendChild(a);if(target.compareDocumentPosition(text)!==20||owner.compareDocumentPosition(a)===20||second.ownerDocument!==target)throw 'actual new root and Attr owner';
"#);}
#[test]
fn inert_position_no_slot_deep_paths_template_roots_and_author_getters(){let(mut d,mut f,mut p)=fixture();p.state.node_limit=d.nodes.len();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),root=owner.createElement('div'),tail=root;owner.appendChild(root);for(var i=0;i<350;i++){var next=owner.createElement('span');tail.appendChild(next);tail=next;}tail.appendChild(owner.createCDATASection('raw\ud800'));if(owner.compareDocumentPosition(tail.firstChild)!==20||tail.firstChild.compareDocumentPosition(root)!==10)throw 'iterative no-slot path';Object.defineProperty(Node.prototype,'parentNode',{configurable:true,get:function(){throw 'author parent getter';}});Object.defineProperty(Node.prototype,'childNodes',{configurable:true,get:function(){throw 'author child getter';}});if(root.compareDocumentPosition(tail)!==20)throw 'native facts';var host=owner.createElementNS('http://www.w3.org/1999/xhtml','template'),ordinary=owner.createTextNode('ordinary'),inside=host.content.ownerDocument.createTextNode('inside');host.appendChild(ordinary);host.content.appendChild(inside);root.appendChild(host);if(host.compareDocumentPosition(ordinary)!==20||host.content.compareDocumentPosition(inside)!==20||(host.compareDocumentPosition(inside)&33)!==33||(owner.compareDocumentPosition(host.content.ownerDocument)&33)!==33)throw 'ordinary and dedicated template roots';
"#);}
#[test]
fn inert_position_saved_child_caller_both_operands_and_teardown_are_guarded(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,saved=w.Node.prototype.compareDocumentPosition,child=w.document.body;if(saved.call(w.document,child)!==20||saved.call(document,document)!==0||(Node.prototype.compareDocumentPosition.call(document,child)&33)!==33)throw 'real child roots';");p.set_location(&crate::navigation::address("https://other-position.test/",&crate::navigation::Location::home()).unwrap());let before=(d.nodes.len(),p.state.retained,p.state.dom_commits);for code in ["saved.call(document,document);","Node.prototype.compareDocumentPosition.call(document,child);","Node.prototype.compareDocumentPosition.call(child,child);"]{assert_eq!(p.console_eval(&mut d,&mut f,code).errors,1);assert_eq!((d.nodes.len(),p.state.retained,p.state.dom_commits),before);}p.set_location(&crate::navigation::address("https://inert-position.test/",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"document.body.removeChild(frame);var caught=false;try{Node.prototype.compareDocumentPosition.call(child,child);}catch(e){caught=true;}if(!caught)throw 'retained teardown before self shortcut';");}
